159	/** A node's whole-subtree cover — its own lines through its deepest last
160	 * descendant's content end, INCLUDING that leaf's own trailing gap in full
161	 * (see `subtreeCoverEnd`). Exported for `select-all-ladder.ts`. */
162	export function subtreeCoverOf(doc: OutlineDoc, node: OutlineNode): Cover {
163	  const start = startLineOf(doc, node);
164	  return { start: { line: start, ch: 0 }, end: subtreeCoverEnd(node, start) };
165	}
166	
167	/** Every node's own absolute start line, in ONE traversal. `startLineOf`
168	 * rescans the document per call, which is fine for the two lookups the
169	 * single-subtree paths need but quadratic for a forest whose root count
170	 * grows with the document (Select All being the limiting case). The
171	 * classification gate that now consumes this geometry runs inside the
172	 * keystroke-latency budget (`transaction-classification`), so the walk
173	 * below stays linear. */
174	function startLineIndex(doc: OutlineDoc): Map<number, number> {
175	  const index = new Map<number, number>();
176	  let line = doc.preamble.length;
177	  const walk = (node: OutlineNode): void => {
178	    index.set(node.id, line);
179	    line += node.lines.length + node.trailingGap.length;
180	    node.children.forEach(walk);
181	  };
182	  doc.children.forEach(walk);
183	  return index;
184	}
185	
186	/** The node following `path`'s WHOLE SUBTREE in document order: the next
187	 * sibling, else the nearest ancestor's next sibling. Distinct from ops.ts's
188	 * `rawSuccessorPath`, which descends into `path`'s own first child instead
189	 * — that one answers "what abuts this node's last line", this one answers
190	 * "what comes after everything this node owns". */
191	function subtreeSuccessorPath(doc: OutlineDoc, path: NodePath): NodePath | undefined {
192	  let p: NodePath = path;
193	  while (p.length > 0) {
194	    const parentPath = p.slice(0, -1);
195	    const index = p[p.length - 1]!;
196	    if (index + 1 < childrenAtScope(doc, parentPath).length) return [...parentPath, index + 1];
197	    p = parentPath;
198	  }
199	  return undefined;
200	}
201	
202	/** One covered root, with everything its consumers would otherwise recompute
203	 * per root by re-walking the document: its `path` (so grouping by parent
204	 * needs no `findPath`) and its own subtree `cover` (so chrome needs no
205	 * `nodeStartLine`/`subtreeCoverOf`). Both are free here — the forest walk
206	 * already holds the path it arrived by and a start-line index — and both
207	 * were Θ(n²) when each consumer derived them itself, which matters most for
208	 * exactly the case this geometry exists to support: a cover with many roots. */
209	export interface ForestRoot {
210	  readonly node: OutlineNode;
211	  readonly path: NodePath;
212	  readonly cover: Cover;
213	}
214	
215	/** A forest of whole subtrees and the single contiguous span covering it.
216	 * `roots` are in document order and may sit at DIFFERENT DEPTHS; grouped by
217	 * parent they form one contiguous sibling run per parent, which is what
218	 * `enforce.ts` hands to `deleteSubtreeGroups`. */
219	export interface ForestCover {
220	  readonly roots: readonly ForestRoot[];
221	  readonly cover: Cover;
222	}
223	
224	/**
225	 * The forest span of two distinct nodes (`selection-as-subtree-set` D2) —
226	 * the shared geometry `escalateRange` (to compute the expand-only union),
227	 * `coveredSubtreeRoots` (to test an existing range against it), and through
228	 * the latter `classify.ts` and `enforce.ts` all read. One implementation,
229	 * every consumer, per that change's D4 and the two silently-stale-duplicate
230	 * incidents in docs/research/04 (Q18, Q19).
231	 *
232	 * When one node is an ancestor of the other, the cover is the ANCESTOR's
233	 * whole subtree — selecting a parent takes its children, unchanged from the
234	 * sibling-run rule this replaces.
235	 *
236	 * Otherwise the roots are the maximal subtrees of the document-order run
237	 * from `firstNode` to `lastNode` closed under descendants, walked here as
238	 * the subtree-successor chain from `firstNode` up to and including the LAST
239	 * ROOT. That last root is the OUTERMOST ancestor-or-self of `lastNode` whose
240	 * own start line is at or after the span's start — NOT `lastNode` itself.
241	 * The distinction is the whole content of D2 and is invisible in the common
242	 * shapes: with
243	 *
244	 *     - P            - S
245	 *       - c1           - t1
246	 *       - c2           - t2
247	 *
248	 * a drag from inside `c2` to inside `t1` ends at `S`'s subtree end, not at
249	 * `t1`'s. Ending at `t1` would put `S`'s entire line in the selection while
250	 * leaving `t2` out — a node selected without its whole subtree, which is
251	 * exactly the downward-closure violation this geometry exists to prevent,
252	 * and which would orphan `t2` on deletion.
253	 *
254	 * The start needs no such qualification: every ancestor of `firstNode`
255	 * begins above it, so none can fall inside the span. The asymmetry is
256	 * inherent to preorder, not a defect in the rule.
257	 *
258	 * The cover's end includes the last root's own trailing gap in full
259	 * (`subtreeCoverEnd`, escalate-include-owned-gap), so reaching a node's
260	 * content by crossing into it is enough to pull its whole gap in — no
261	 * separate drag onto the blank line required.
262	 */
263	export function forestCoverOf(
264	  doc: OutlineDoc,
265	  anchorNode: OutlineNode,
266	  headNode: OutlineNode,
267	): ForestCover {
268	  const anchorPath = findPath(doc, anchorNode.id)!;
269	  const headPath = findPath(doc, headNode.id)!;
270	  const startLines = startLineIndex(doc);
271	  const startOf = (node: OutlineNode): number => startLines.get(node.id)!;
272	
273	  const isPrefix = (a: NodePath, b: NodePath): boolean =>
274	    a.length < b.length && a.every((index, i) => index === b[i]);
275	
276	  // One end's node is an ancestor of the other's: the ancestor's whole
277	  // subtree is the cover, and it is the only root.
278	  if (isPrefix(anchorPath, headPath)) {
279	    return singleRootCover(anchorNode, anchorPath, startOf(anchorNode));
280	  }
281	  if (isPrefix(headPath, anchorPath)) {
282	    return singleRootCover(headNode, headPath, startOf(headNode));
283	  }
284	
285	  const forward = startOf(anchorNode) <= startOf(headNode);
286	  const firstNode = forward ? anchorNode : headNode;
287	  const lastNode = forward ? headNode : anchorNode;
288	  const firstPath = forward ? anchorPath : headPath;
289	  const lastPath = forward ? headPath : anchorPath;
290	  const spanStart = startOf(firstNode);
291	
292	  // The outermost ancestor-or-self of `lastNode` that begins at or after
293	  // the span's start. Start lines increase monotonically along a path, so
294	  // the shallowest prefix that qualifies is the answer and every deeper one
295	  // qualifies too.
296	  let lastRoot = lastNode;
297	  for (let depth = 1; depth < lastPath.length; depth++) {
298	    const ancestor = nodeAt(doc, lastPath.slice(0, depth))!;
299	    if (startOf(ancestor) >= spanStart) {
300	      lastRoot = ancestor;
301	      break;
302	    }
303	  }
304	
305	  // Walk the subtree-successor chain from `firstNode` to `lastRoot`. Every
306	  // node it emits is a maximal subtree of the span: the chain never
307	  // descends, so no emitted node is inside another's subtree, and `lastRoot`
308	  // is always reached — were it inside some earlier emitted subtree, that
309	  // subtree's root would be a SHALLOWER ancestor of `lastNode` starting at
310	  // or after `spanStart`, contradicting `lastRoot`'s outermost-ness.
311	  const roots: ForestRoot[] = [];
312	  let path: NodePath | undefined = firstPath;
313	  while (path) {
314	    const node = nodeAt(doc, path)!;
315	    const start = startOf(node);
316	    roots.push({
317	      node,
318	      path,
319	      cover: { start: { line: start, ch: 0 }, end: subtreeCoverEnd(node, start) },
320	    });
321	    if (node === lastRoot) break;
322	    path = subtreeSuccessorPath(doc, path);
323	  }
324	
325	  return {
326	    roots,
327	    cover: {
328	      start: { line: spanStart, ch: 0 },
329	      end: subtreeCoverEnd(lastRoot, startOf(lastRoot)),
330	    },
331	  };
332	}
333	
334	function singleRootCover(node: OutlineNode, path: NodePath, startLine: number): ForestCover {
335	  const cover: Cover = {
336	    start: { line: startLine, ch: 0 },
337	    end: subtreeCoverEnd(node, startLine),
338	  };
339	  return { roots: [{ node, path, cover }], cover };
340	}
341	
342	/**
343	 * The expand-only invariant (D4 amendment): the escalated range is the
344	 * UNION of the computed cover and the original range — escalation only
345	 * ever moves ends outward, never pulls one back. Without this, an end the
346	 * user placed beyond the cover (a trailing gap line, the document's final
347	 * empty line) would be dragged back to the last content character —
348	 * concretely, Select All in a no-frontmatter note would silently drop its
349	 * trailing newline from the selection (sharpest in a single-node note,
350	 * where the head-on-final-gap-line shape is exactly the gap-line trigger).
351	 * Returns the ORIGINAL range object when the union changes nothing, so
352	 * callers can use identity/equality to detect a real escalation.
353	 */
354	function expandToCover(range: LineRange, cover: Cover): LineRange {
355	  const lo = isBackward(range) ? range.head : range.anchor;
356	  const hi = isBackward(range) ? range.anchor : range.head;
357	  const newLo = posBefore(cover.start, lo) ? cover.start : lo;
358	  const newHi = posBefore(hi, cover.end) ? cover.end : hi;
359	  if (posEqual(newLo, lo) && posEqual(newHi, hi)) return range;
360	  return isBackward(range) ? { anchor: newHi, head: newLo } : { anchor: newLo, head: newHi };
361	}
362	
363	/**
364	 * Escalate one selection range per D4 (as amended). Returns `range`
365	 * unchanged for: empty ranges (cursors — never altered), ranges with
366	 * either end in the preamble (D5 jurisdiction), and ranges whose ends both
367	 * rest on a single node's own content lines. Escalates to the node's whole
368	 * subtree when a same-node range has an end on a trailing gap line (the
369	 * single-node-selection trigger), and to the FOREST SPAN of the two ends
370	 * when they resolve to different nodes (`forestCoverOf`) — in both cases
371	 * unioned with the original range (expand-only) and with orientation
372	 * preserved.
373	 */
374	export function escalateRange(doc: OutlineDoc, range: LineRange): LineRange {
375	  if (isEmpty(range)) return range;
376	
377	  const anchorNode = nodeAtLine(doc, range.anchor.line);
378	  const headNode = nodeAtLine(doc, range.head.line);
379	  if (!anchorNode || !headNode) return range; // preamble jurisdiction (D5)
380	
381	  if (anchorNode === headNode) {
382	    // Same node: untouched while both ends stay on the node's own content
383	    // lines; an end on a trailing gap line escalates to this one node's
384	    // subtree (the drag-past-the-end-selects-the-node gesture).
385	    const start = startLineOf(doc, anchorNode);
386	    const firstGapLine = start + anchorNode.lines.length;
387	    if (range.anchor.line < firstGapLine && range.head.line < firstGapLine) return range;
388	    return expandToCover(range, subtreeCoverOf(doc, anchorNode));
389	  }
390	
391	  return expandToCover(range, forestCoverOf(doc, anchorNode, headNode).cover);
392	}
393	
394	/**
395	 * Escalate a full selection's ranges with the uniform multi-range rule (D4
396	 * amendment): every range is first escalated independently; if ANY range
397	 * escalated, every other non-empty in-jurisdiction range is then escalated
398	 * to at least its own node's whole subtree. The result is that an
399	 * escalated multi-range selection is always a set of whole-subtree ranges
400	 * — a multi-range copy concatenates complete subtrees, never a mix of
401	 * block-level and mid-node fragments. Cursors and preamble ranges are
402	 * never touched; when nothing escalates, all ranges come back unchanged.
403	 */
404	export function escalateRanges(doc: OutlineDoc, ranges: readonly LineRange[]): LineRange[] {
405	  const escalated = ranges.map((range) => escalateRange(doc, range));
406	  const anyEscalated = escalated.some((range, i) => !rangesEqual(range, ranges[i]!));
407	  if (!anyEscalated) return escalated;
408	
409	  return escalated.map((range, i) => {
410	    if (!rangesEqual(range, ranges[i]!)) return range; // already escalated
411	    if (isEmpty(range)) return range; // cursors never move (this function's own scope — see ./caret.ts's resolvePlacement for cursor placement)
412	    const anchorNode = nodeAtLine(doc, range.anchor.line);
413	    const headNode = nodeAtLine(doc, range.head.line);
414	    if (!anchorNode || !headNode) return range; // preamble jurisdiction
415	    // An unchanged non-empty in-jurisdiction range is a same-node content
416	    // range — force it up to its node's whole subtree. (expandToCover also
417	    // makes the already-exact-cover case a clean no-op.)
418	    return expandToCover(range, subtreeCoverOf(doc, anchorNode));
419	  });
420	}
421	
422	/**
423	 * The escalated-selection-decoration query (docs/research/13, "Escalated-
424	 * selection visual treatment"): does `range`'s current bounds cover a
425	 * single node's whole subtree, or the combined cover of a FOREST of whole
426	 * subtrees at possibly different depths? Returns the covered subtree roots
427	 * (length 1 for a single-node cover) when so, `null` otherwise.
428	 *
429	 * Three consumers beyond the selection chrome read this, and they read it
430	 * for different reasons, so widening what it recognizes widens all of them
431	 * at once (`selection-as-subtree-set` D4): `enforce.ts`'s `coverIdsOf` and
432	 * `computeMultiRangeDeletionVerdict` turn the roots into deletion groups,
433	 * and `classify.ts`'s `isExactSubtreeCoverDeletion` uses a non-`null`
434	 * answer as a CLASSIFICATION GATE — the test that routes an exact-cover
435	 * deletion to the verdict layer even though its raw line span reads as
436	 * within-node.
437	 *
438	 * The match is `lo` at the cover's exact start AND `hi` at-or-beyond the
439	 * cover's end — NOT strict equality on both ends. `cover.end` is already
440	 * gap-inclusive (`subtreeCoverEnd`, escalate-include-owned-gap), so for an
441	 * escalated range `hi` almost always lands exactly on it; `!posBefore(hi,
442	 * cover.end)` rather than strict equality is kept for robustness (`hi`
443	 * cannot stray past this node/run's own territory without `headNode`
444	 * resolving to a different node and taking the other branch below) and
445	 * because it's what makes an exact single-line leaf match (no gap at all,
446	 * `hi` lands precisely on `cover.end`) qualify too, satisfying the "any
447	 * exact cover, leaf included" decision in design.md with no separate case
448	 * for it.
449	 *
450	 * Stateless and history-independent by design: this asks "does the CURRENT
451	 * selection cover this subtree," not "was this selection produced by
452	 * escalation" — a plain native selection that happens to match (e.g. Home
453	 * then Shift+End on a single-line paragraph) is indistinguishable from an
454	 * escalated one, and is meant to be: the same thing is selected either way.
455	 */
456	export function coveredForestOf(doc: OutlineDoc, range: LineRange): ForestCover | null {
457	  if (isEmpty(range)) return null;
458	
459	  const lo = isBackward(range) ? range.head : range.anchor;
460	  const hi = isBackward(range) ? range.anchor : range.head;
461	  const anchorNode = nodeAtLine(doc, lo.line);
462	  const headNode = nodeAtLine(doc, hi.line);
463	  if (!anchorNode || !headNode) return null; // preamble jurisdiction
464	
465	  const forest =
466	    anchorNode === headNode
467	      ? singleRootCover(anchorNode, findPath(doc, anchorNode.id)!, startLineOf(doc, anchorNode))
468	      : forestCoverOf(doc, anchorNode, headNode);
469	
470	  return posEqual(lo, forest.cover.start) && !posBefore(hi, forest.cover.end) ? forest : null;
471	}
472	
473	/**
474	 * `coveredForestOf` projected to just the root NODES — the shape three of
475	 * the four consumers want. Kept as its own export because it is the name the
476	 * decoration, classification and deletion call sites already read as "is
477	 * this range a cover, and of what".
478	 */
479	export function coveredSubtreeRoots(doc: OutlineDoc, range: LineRange): readonly OutlineNode[] | null {
480	  return coveredForestOf(doc, range)?.roots.map((r) => r.node) ?? null;
481	}
