18	  let line = doc.preamble.length;
19	  let found = -1;
20	  const walk = (node: OutlineNode): void => {
21	    if (found !== -1) return;
22	    if (node.id === id) {
23	      found = line;
24	      return;
25	    }
26	    line += node.lines.length + node.trailingGap.length;
27	    node.children.forEach(walk);
28	  };
29	  doc.children.forEach(walk);
30	  return found;
31	}
