33	export function nodeAtLine(doc: OutlineDoc, line: number): OutlineNode | undefined {
34	  let current = doc.preamble.length;
35	  if (line < current) return undefined;
36	  let found: OutlineNode | undefined;
37	  const walk = (node: OutlineNode): void => {
38	    if (found) return;
39	    const end = current + node.lines.length + node.trailingGap.length;
40	    if (line < end) {
41	      found = node;
42	      // Descend no further: children come after this node's own span.
43	      return;
44	    }
45	    current = end;
46	    node.children.forEach(walk);
47	  };
48	  doc.children.forEach(walk);
