import { describe, it } from 'vitest';
import { parse } from '../src/parse';
import { escalateRange, type LineRange, type LinePos } from '../src/escalate';

const LINES = ['- P', '\t- c1', '\t- c2', '- Q'];
const doc = parse(LINES.join('\n'));

/** Native line-wise extension: head moves one line, goal column preserved,
 * clamped to the line's length. Anchor never moves. This is the half of
 * today's behavior that CM6 provides; escalateRange is the half we own. */
function nativeExtend(r: LineRange, dir: -1 | 1, goal: number): LineRange {
  const line = Math.max(0, Math.min(LINES.length - 1, r.head.line + dir));
  return { anchor: r.anchor, head: { line, ch: Math.min(goal, LINES[line]!.length) } };
}

function render(r: LineRange): string {
  const lo = r.anchor.line <= r.head.line ? r.anchor : r.head;
  const hi = r.anchor.line <= r.head.line ? r.head : r.anchor;
  const marked = LINES.map((text, i) => {
    const inside = i >= lo.line && i <= hi.line;
    return `${inside ? '█' : ' '}${text}`;
  });
  const o = r.head.line < r.anchor.line || (r.head.line === r.anchor.line && r.head.ch < r.anchor.ch);
  return `${marked.join('  |  ')}   [${o ? 'back' : 'fwd'} a=${r.anchor.line},${r.anchor.ch} h=${r.head.line},${r.head.ch}]`;
}

