  });

  it('climbs from a re-seated single-root cover (design D8)', () => {
    const swallowed = extended(1, ['up', 'up']); // [P] — anchor re-seated onto P
    expect(spanOf(swallowed)).toBe('0..2 back');
    expect(spanOf(nextRung(doc, swallowed))).toBe('0..3 back'); // the outline body
  });
});

describe('property: extension and the ladder compose through the selection alone', () => {
  it('a selection behaves the same however it was reached', () => {
    let checked = 0;
    fc.assert(
      fc.property(arbTree(), fc.nat(), fc.constantFrom<ExtendDirection>('up', 'down'),
        (tree, pick, direction) => {
          const text = encode(tree);
          const lines = text === '' ? [] : text.split('\n');
          const d = parse(text);
          const candidates: number[] = [];
          for (let i = 0; i < lines.length; i++) if (nodeAtLine(d, i)) candidates.push(i);
          if (candidates.length === 0) return true;
          const line = candidates[pick % candidates.length]!;

          // Reach a selection two different ways, then apply the SAME second
          // gesture to each and to the selection itself. Independence means
          // the second gesture's answer depends only on where we are.
          const viaExtension = extendSelection(d, cursor(pos(line, 0)), direction);
          if (!viaExtension) return true;
          const viaLadder = nextRung(d, cursor(pos(line, 0)));
          if (!viaLadder) return true;

          for (const reached of [viaExtension, viaLadder]) {
            checked++;
            // Extension from `reached` must not depend on which produced it:
            // both are just LineRanges, so the only way this could differ is
            // if either module consulted provenance. Assert against a fresh
            // structural copy, which carries no history whatsoever.
            const copy: LineRange = {
              anchor: { ...reached.anchor },
              head: { ...reached.head },
            };
            expect(extendSelection(d, copy, direction)).toEqual(
              extendSelection(d, reached, direction),
            );
            expect(nextRung(d, copy)).toEqual(nextRung(d, reached));
          }
          return true;
        }),
      { numRuns: 150 },
    );
    expect(checked).toBeGreaterThan(100); // not vacuous
  });
});
